using System;
using System.Collections.Generic;
using UnityEngine;

namespace Yixuan.World
{
    /// <summary>
    /// Unified, stable-id entity/capability catalog shared by the big map, world
    /// queries, pick/vision target confirmation and the interaction controllers.
    /// Generated by Tools/SeatExpansion/make_entity_catalog_v1.py from the
    /// read-only world inventory plus verified seat parameters. Capability state
    /// is deliberately split into code_implemented / geometry_verified /
    /// reachable (runtime) / tested so no single boolean hides a missing step.
    /// </summary>
    public static class WorldEntityCatalog
    {
        public const string ResourcePath = "SovietBlueHour/entity_catalog.v1";

        [Serializable]
        public class Capability
        {
            public string verb;
            public bool code_implemented;
            public bool geometry_verified;
            public bool geometry_usable;
            public string reachable;
            public bool tested;
            public string reason;
        }

        [Serializable]
        public class ApproachCandidate
        {
            public string side;
            public float[] position_unity;
            public float yaw_deg;
            public float clearance_m;
        }

        [Serializable]
        public class SeatInfo
        {
            public bool usable;
            public float seat_yaw_deg;
            public float[] seat_point;
            public float[] approach_point;
            public float seat_height_above_ground_m;
            public ApproachCandidate[] approach_candidates;
            public bool nav_obstacle_covered;
            public string gate_status;
            public string[] errors;
        }

        [Serializable]
        public class Entity
        {
            public string id;
            public string cls;
            public string kind;
            public string name;
            public string english;
            public string group;
            public string display_name;
            public string display_family;
            public int display_number;
            public string area;
            public string area_source;
            public float[] pos;
            public float[] bounds;
            public float height;
            public float yaw;
            public bool selectable;
            public bool blocks_navigation;
            public bool nav_obstacle_covered;
            public Capability[] capabilities;
            public SeatInfo seat;
            public string source;
        }

        [Serializable]
        public class Anchor
        {
            public string id;
            public string label;
            public float[] pos;
            public string source;
        }

        [Serializable]
        public class Counts
        {
            public int entities;
            public int benches;
            public int usable_benches;
            public int vehicles;
            public int anchors;
        }

        [Serializable]
        public class Sources
        {
            public string world_map_sha256;
            public string seat_params_sha256;
            public string nav_obstacles_sha256;
            public string anchors_sha256;
            public string plan_sha256;
        }

        [Serializable]
        public class Doc
        {
            public string schema;
            public string data_version;
            public string map_version;
            public float[] spawn;
            public float spawn_yaw;
            public Counts counts;
            public Sources sources;
            public Anchor[] anchors;
            public Entity[] entities;
        }

        public static bool Loaded { get; private set; }
        public static string Error { get; private set; }
        public static Doc Data { get; private set; }

        static readonly Dictionary<string, Entity> ById = new Dictionary<string, Entity>(StringComparer.Ordinal);
        static readonly List<Entity> EmptyList = new List<Entity>();

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void Boot() { EnsureLoaded(); }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetSession()
        {
            Loaded = false;
            Error = null;
            Data = null;
            ById.Clear();
        }

        /// <summary>
        /// Install an explicit, scene-owned catalog (whitebox lab / future generated
        /// spaces). This is authoritative for the current scene; no Soviet resource
        /// is read while it is installed.
        /// </summary>
        public static void UseExplicit(Doc doc)
        {
            Loaded = false;
            Error = null;
            Data = doc;
            ById.Clear();
            if (Data != null && Data.entities != null)
            {
                foreach (var entity in Data.entities)
                {
                    if (entity == null || string.IsNullOrEmpty(entity.id) || ById.ContainsKey(entity.id)) continue;
                    ById[entity.id] = entity;
                }
                Loaded = true;
            }
        }

        /// <summary>Drop explicit lab data so the next scene can load its own source.</summary>
        public static void ResetExplicit()
        {
            Loaded = false;
            Error = null;
            Data = null;
            ById.Clear();
        }

        public static bool EnsureLoaded()
        {
            if (Loaded) return Data != null;
            Error = null;
            try
            {
                var asset = Resources.Load<TextAsset>(ResourcePath);
                if (asset == null)
                {
                    Error = "缺少 Resources/" + ResourcePath + ".json";
                    Debug.LogError("[WorldEntityCatalog] " + Error);
                    return false;
                }
                Data = JsonUtility.FromJson<Doc>(asset.text);
                if (Data == null || Data.entities == null || Data.entities.Length == 0)
                {
                    Error = "实体目录 JSON 结构不完整";
                    Debug.LogError("[WorldEntityCatalog] " + Error);
                    return false;
                }
                ById.Clear();
                foreach (var entity in Data.entities)
                {
                    if (string.IsNullOrEmpty(entity.id) || ById.ContainsKey(entity.id)) continue;
                    ById[entity.id] = entity;
                }
                Loaded = true;
                Debug.Log("[WorldEntityCatalog] 载入实体=" + ById.Count + "，椅子=" +
                          (Data.counts != null ? Data.counts.benches : -1) + "，可用椅子=" +
                          (Data.counts != null ? Data.counts.usable_benches : -1) +
                          "，地图版本=" + Data.map_version);
                return true;
            }
            catch (Exception e)
            {
                Error = "实体目录载入异常：" + e.Message;
                Debug.LogError("[WorldEntityCatalog] " + Error);
                return false;
            }
        }

        public static Entity Get(string id)
        {
            EnsureLoaded();
            if (string.IsNullOrEmpty(id)) return null;
            Entity entity;
            return ById.TryGetValue(id, out entity) ? entity : null;
        }

        public static int Count { get { EnsureLoaded(); return Data != null ? Data.entities.Length : 0; } }

        public static Entity[] All { get { EnsureLoaded(); return Data != null ? Data.entities : new Entity[0]; } }

        public static Anchor[] Anchors { get { EnsureLoaded(); return Data != null ? Data.anchors : new Anchor[0]; } }

        public static Vector3 Spawn
        {
            get
            {
                EnsureLoaded();
                if (Data == null || Data.spawn == null || Data.spawn.Length < 3) return Vector3.zero;
                return new Vector3(Data.spawn[0], Data.spawn[1], Data.spawn[2]);
            }
        }

        public static Vector3 WorldPosition(Entity entity)
        {
            if (entity == null || entity.pos == null || entity.pos.Length < 3) return Vector3.zero;
            if (!string.IsNullOrEmpty(entity.id))
            {
                var dynamicWorld = Yixuan.Dynamic.DynamicWorld.Instance;
                if (dynamicWorld != null)
                {
                    var live = dynamicWorld.CurrentPositionOf(entity.id);
                    if (live.HasValue) return live.Value;
                }
            }
            return new Vector3(entity.pos[0], entity.pos[1], entity.pos[2]);
        }

        public static Vector3? SeatPoint(Entity entity)
        {
            if (entity == null || entity.seat == null || entity.seat.seat_point == null ||
                entity.seat.seat_point.Length < 3) return null;
            var p = entity.seat.seat_point;
            return new Vector3(p[0], p[1], p[2]);
        }

        public static Vector3? ApproachPoint(Entity entity)
        {
            if (entity == null || entity.seat == null || entity.seat.approach_point == null ||
                entity.seat.approach_point.Length < 3) return null;
            var p = entity.seat.approach_point;
            return new Vector3(p[0], p[1], p[2]);
        }

        public static Capability CapabilityOf(Entity entity, string verb)
        {
            if (entity == null || entity.capabilities == null) return null;
            foreach (var capability in entity.capabilities)
            {
                if (capability != null && capability.verb == verb) return capability;
            }
            return null;
        }

        public static bool HasImplementedCapability(Entity entity, string verb)
        {
            var capability = CapabilityOf(entity, verb);
            return capability != null && capability.code_implemented && capability.geometry_verified;
        }

        public static string DisplayName(Entity entity)
        {
            if (entity == null) return "";
            return string.IsNullOrEmpty(entity.display_name) ? entity.name : entity.display_name;
        }

        /// <summary>Filter entities for the big map. Null/empty text matches everything.</summary>
        public static List<Entity> Query(string cls, string text, int max)
        {
            EnsureLoaded();
            var result = new List<Entity>();
            if (Data == null) return result;
            string needle = string.IsNullOrEmpty(text) ? null : text.Trim().ToLowerInvariant();
            foreach (var entity in Data.entities)
            {
                if (entity == null) continue;
                if (!string.IsNullOrEmpty(cls) && entity.cls != cls) continue;
                if (needle != null)
                {
                    bool hit = (entity.name != null && entity.name.ToLowerInvariant().Contains(needle)) ||
                               (entity.display_name != null && entity.display_name.ToLowerInvariant().Contains(needle)) ||
                               (entity.id != null && entity.id.ToLowerInvariant().Contains(needle)) ||
                               (entity.english != null && entity.english.ToLowerInvariant().Contains(needle)) ||
                               (entity.area != null && entity.area.ToLowerInvariant().Contains(needle));
                    if (!hit) continue;
                }
                result.Add(entity);
                if (max > 0 && result.Count >= max) break;
            }
            return result;
        }

        public static List<Entity> Nearby(Vector3 around, float maxDistance, string cls, int max)
        {
            EnsureLoaded();
            var result = new List<Entity>();
            if (Data == null) return result;
            float maxSqr = maxDistance * maxDistance;
            var scored = new List<KeyValuePair<float, Entity>>();
            foreach (var entity in Data.entities)
            {
                if (entity == null) continue;
                if (!string.IsNullOrEmpty(cls) && entity.cls != cls) continue;
                Vector3 position = WorldPosition(entity);
                float dx = position.x - around.x;
                float dz = position.z - around.z;
                float sqr = dx * dx + dz * dz;
                if (sqr > maxSqr) continue;
                scored.Add(new KeyValuePair<float, Entity>(sqr, entity));
            }
            scored.Sort((a, b) => a.Key.CompareTo(b.Key));
            foreach (var pair in scored)
            {
                result.Add(pair.Value);
                if (max > 0 && result.Count >= max) break;
            }
            return result;
        }
    }
}
